import{_ as a,c as e,o as n,a2 as s}from"./chunks/framework.PGES7OoM.js";const g=JSON.parse('{"title":"Introduction to actions","description":"Understand and browse the Curvy SDK\'s public actions.","frontmatter":{"title":"Introduction to actions","description":"Understand and browse the Curvy SDK\'s public actions.","rawMarkdown":"---\\ntitle: Introduction to actions\\ndescription: Understand and browse the Curvy SDK\'s public actions.\\n---\\n\\n# Introduction to actions\\n\\nActions are standalone functions that read or change Curvy state. They are imported from `@0xcurvy/curvy-sdk/actions` and operate through a [`CurvyConfig`](/sdk/config/).\\n\\n```ts\\nimport { getBalances, refreshBalances } from \\"@0xcurvy/curvy-sdk/actions\\";\\n\\nawait refreshBalances({ config });\\nconst balances = await getBalances({ config });\\n```\\n\\n## Parameters\\n\\nMost actions use parameter objects so optional values remain explicit and signatures can evolve without positional arguments. Event subscription actions retain a natural listener signature.\\n\\n```ts\\nconst balances = await getBalances({ // [!code focus:5]\\n  accountId,\\n  cached: false,\\n  config,\\n});\\n```\\n\\nThe `config` property is optional when an ambient browser config exists. Pass it explicitly in shared libraries, tests, and server applications.\\n\\n## Action groups\\n\\n| Group | Purpose |\\n| --- | --- |\\n| Account | Manage accounts, active-account state, keys, and subscriptions. |\\n| Authentication | Register, log in, restore sessions, and log out. |\\n| Balances | Read balances and control note synchronization. |\\n| Networks | Read networks, switch environments, and resolve Curvy IDs. |\\n| Events | Subscribe and unsubscribe from typed SDK events. |\\n| History | Read user-facing transaction and intent history. |\\n| Planner | Estimate intents, present sanitized steps, and execute prepared intents. |\\n| Aggregator | Build, submit, relay, and price private transactions. |\\n| Bridge | Estimate cross-chain bridge routes. |\\n| Portals | Generate and inspect entry and exit Portals. |\\n| Recovery | Find owned Portals and recover assets. |\\n| Notes | Synchronize notes and resolve spend witnesses. |\\n| Proving | Generate aggregation and withdrawal proofs. |\\n| Storage | Reset and reconstruct SDK-derived storage. |\\n\\nEvery public action is available in the Actions navigation. Each reference page contains its import, usage, signature, return type, parameters, errors, and source.\\n\\n## High-level and low-level actions\\n\\nPrefer high-level actions such as [`aggregate`](/sdk/actions/aggregator/aggregate), [`withdraw`](/sdk/actions/aggregator/withdraw), and [`executeIntent`](/sdk/actions/planner/executeIntent) for ordinary application flows. Builder, proving, and submission actions are available when an integration needs control over an intermediate step.\\n\\n## Errors\\n\\nActions propagate typed SDK errors and errors from their underlying runtime or transport. Handle errors at the boundary where the application can offer a meaningful retry or recovery path.\\n","rawMarkdownPath":"/_raw/sdk/actions/index.md","rawMarkdownTitle":"Introduction to actions","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/index.md"},"headers":[],"relativePath":"sdk/actions/index.md","filePath":"sdk/actions/index.md","lastUpdated":1786521734000}'),i={name:"sdk/actions/index.md"};function r(o,t,d,c,l,h){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="introduction-to-actions" tabindex="-1">Introduction to actions <a class="header-anchor" href="#introduction-to-actions" aria-label="Permalink to &quot;Introduction to actions&quot;">​</a></h1><p>Actions are standalone functions that read or change Curvy state. They are imported from <code>@0xcurvy/curvy-sdk/actions</code> and operate through a <a href="/sdk/config/"><code>CurvyConfig</code></a>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { getBalances, refreshBalances } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@0xcurvy/curvy-sdk/actions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> refreshBalances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ config });</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> balances</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getBalances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ config });</span></span></code></pre></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><p>Most actions use parameter objects so optional values remain explicit and signatures can evolve without positional arguments. Event subscription actions retain a natural listener signature.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark has-focused-lines vp-code" tabindex="0"><code><span class="line has-focus"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> balances</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getBalances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span></span>
<span class="line has-focus"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  accountId,</span></span>
<span class="line has-focus"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  cached: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line has-focus"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  config,</span></span>
<span class="line has-focus"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>The <code>config</code> property is optional when an ambient browser config exists. Pass it explicitly in shared libraries, tests, and server applications.</p><h2 id="action-groups" tabindex="-1">Action groups <a class="header-anchor" href="#action-groups" aria-label="Permalink to &quot;Action groups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Purpose</th></tr></thead><tbody><tr><td>Account</td><td>Manage accounts, active-account state, keys, and subscriptions.</td></tr><tr><td>Authentication</td><td>Register, log in, restore sessions, and log out.</td></tr><tr><td>Balances</td><td>Read balances and control note synchronization.</td></tr><tr><td>Networks</td><td>Read networks, switch environments, and resolve Curvy IDs.</td></tr><tr><td>Events</td><td>Subscribe and unsubscribe from typed SDK events.</td></tr><tr><td>History</td><td>Read user-facing transaction and intent history.</td></tr><tr><td>Planner</td><td>Estimate intents, present sanitized steps, and execute prepared intents.</td></tr><tr><td>Aggregator</td><td>Build, submit, relay, and price private transactions.</td></tr><tr><td>Bridge</td><td>Estimate cross-chain bridge routes.</td></tr><tr><td>Portals</td><td>Generate and inspect entry and exit Portals.</td></tr><tr><td>Recovery</td><td>Find owned Portals and recover assets.</td></tr><tr><td>Notes</td><td>Synchronize notes and resolve spend witnesses.</td></tr><tr><td>Proving</td><td>Generate aggregation and withdrawal proofs.</td></tr><tr><td>Storage</td><td>Reset and reconstruct SDK-derived storage.</td></tr></tbody></table><p>Every public action is available in the Actions navigation. Each reference page contains its import, usage, signature, return type, parameters, errors, and source.</p><h2 id="high-level-and-low-level-actions" tabindex="-1">High-level and low-level actions <a class="header-anchor" href="#high-level-and-low-level-actions" aria-label="Permalink to &quot;High-level and low-level actions&quot;">​</a></h2><p>Prefer high-level actions such as <a href="/sdk/actions/aggregator/aggregate.html"><code>aggregate</code></a>, <a href="/sdk/actions/aggregator/withdraw.html"><code>withdraw</code></a>, and <a href="/sdk/actions/planner/executeIntent.html"><code>executeIntent</code></a> for ordinary application flows. Builder, proving, and submission actions are available when an integration needs control over an intermediate step.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Actions propagate typed SDK errors and errors from their underlying runtime or transport. Handle errors at the boundary where the application can offer a meaningful retry or recovery path.</p>`,14)])])}const u=a(i,[["render",r]]);export{g as __pageData,u as default};
